package hr.algebra.kompassgo.model;

import java.util.Objects;


public class Location {

    private int id;
    private int userId;
    private String name;
    private String address;

    public Location() {
    }

    // READ FROM DB
    public Location(int id, int userId, String name, String address) {
        this.id = id;
        this.userId = userId;
        this.name = name;
        this.address = address;
    }

    // NEW LOCATION: the ID is generated by the database
    public Location(int userId, String name, String address) {
        this.userId = userId;
        this.name = name;
        this.address = address;
    }

    public int getId() { return id; }
    public void setId(int id) { this.id = id; }

    public int getUserId() { return userId; }
    public void setUserId(int userId) { this.userId = userId; }

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public String getAddress() { return address; }
    public void setAddress(String address) { this.address = address; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Location other)) return false;
        return id == other.id && userId == other.userId && Objects.equals(name, other.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, userId, name);
    }


    @Override
    public String toString() {
        return name;
    }
}